///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_ToExcel
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_ToExcel = async function () {
    const sbmOptions = {
        id: "tx_fn_ToExcel",
        method: "post",
        action: "/helper/schedule.do",
        ref: "dma_ToExcelReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil35600.tx_fn_ToExcel" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_findSchedules_xhr
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_findSchedules_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_findSchedules_xhr", unresolved: "action:self_submit:tx_fn_findSchedules_xhr" };
};


///////// 5. 일반/업무 함수 영역 /////////

async function list() {
    /* sdd-asis-lifecycle:begin fn_List — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $("#listTab").removeClass().addClass("on");
    $("#calTab").removeClass();
    $c.util.getComponent("dma_ToExcelReq").set("displayDiv", "list");
    await scwin.findSchedules();
    /* sdd-asis-lifecycle:end */
}

async function calendar() {
    /* sdd-asis-lifecycle:begin fn_Calendar — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $("#calTab").removeClass().addClass("on");
    $("#listTab").removeClass();
    $c.util.getComponent("dma_ToExcelReq").set("displayDiv", "calendar");
    await scwin.findSchedules();
    /* sdd-asis-lifecycle:end */
}

