    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.schedules2
 * @author Inswave
 * @date 2026. 09. 29
 * @param month
 * @returns
 * @hidden N
*/
scwin.schedules2 = async function (month) {
    /* sdd-asis-lifecycle:begin fn_Schedules2 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $("#monthListArea").children("li").each(function(i) {
            $(this).find("a").removeClass();
            if ((i + 1) === Number(month)) {
                $(this).find("a").addClass("on");
            }
    });
    $c.util.getComponent("dma_ToExcelReq").set("month", month);
    await scwin.findSchedules();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
