    scwin.form_listForm.action = "/helper/schedule.do";
    $c.util.getComponent("dma_ToExcelReq").set("method", "findDisclosureSchedules");
    $c.util.getComponent('txt_scheduleDiv').setValue(await scwin.tx_fn_findSchedules_xhr());
    /* sdd-asis-lifecycle:end */
};


