scwin.findSchedule = function (calndDd, byddSeq) {
    /* sdd-asis-lifecycle:begin fn_findSchedule — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _url = "/helper/schedule.do?method=findDisclosureSchedule&calndDd=" + calndDd + "&byddSeq=" + byddSeq;
    console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
